	@Test
	void nativeCancellationStopsAnInProgressExactRangeWalkAndClosesItsReadView(@TempDir Path directory)
			throws Exception {
		try (Environment env = new Environment(directory, 0)) {
			env.write(0, 10_000);
			long txn = env.begin(MDB_RDONLY);
			try {
				byte[] lower = key(1);
				byte[] upper = key(19);
				AtomicInteger polls = new AtomicInteger();
				CountDownLatch walkStarted = new CountDownLatch(1);
				CountDownLatch continueWalk = new CountDownLatch(1);
				try (var view = env.estimator.readTransaction(txn, 1L)) {
					assertThrows(KernelQueryCancelledException.class,
							() -> NativeCancellationTestAccess.cancelAfter(walkStarted, continueWalk,
									() -> view.countEntriesExact("records", lower, lower.length, true, upper,
											upper.length, false, () -> {
												if (polls.incrementAndGet() == 12) {
													walkStarted.countDown();
													awaitLatch(continueWalk);
													NativeLmdbQuerySource.checkpointCancellation();
												}
												NativeLmdbQuerySource.checkpointCancellation();
												return false;
											})));
					assertEquals(12, polls.get(), "cancellation is requested after page-walk polling begins");
					view.close();
					assertThrows(IllegalStateException.class, () -> view.countEntriesExact("records", lower,
							lower.length, true, upper, upper.length, false, () -> false));
					try (var reopened = env.estimator.readTransaction(txn, 1L)) {
						assertEquals(9_000, reopened.countEntriesExact("records", lower, lower.length, true,
								upper, upper.length, false, () -> false).entries());
					}
				}
			} finally {
				mdb_txn_abort(txn);
			}
		}
	}

	@Test
	void nativeBytewiseKeysRetainFullUnsignedPrefixOrdering(@TempDir Path directory) throws Exception {
		long[] values = { 240L, 241L, Long.MAX_VALUE, Long.MIN_VALUE, -1L };
		try (Environment env = new Environment(directory, 0)) {
			env.writeUnsignedPrefixes(values);
			long txn = env.begin(MDB_RDONLY);
			try (var view = env.estimator.readTransaction(txn, 1L);
					var cursor = view.prefixRunsExact("records", null, 0, true, null, 0, true, 1, () -> false)) {
				for (long expected : values) {
					PrefixRun run = cursor.next();
					assertNotNull(run);
					assertEquals(expected, Varint.readUnsigned(ByteBuffer.wrap(run.representativeKey())));
					assertEquals(2, run.entries());
				}
				assertNull(cursor.next());
				byte[] lower = unsignedKey(Long.MIN_VALUE, 0);
				byte[] upper = unsignedKey(-1L, 1);
				assertEquals(4, view.countEntriesExact("records", lower, lower.length, true,
						upper, upper.length, true, () -> false).entries());
			} finally {
				mdb_txn_abort(txn);
			}
		}
	}

	private static byte[] unsignedKey(long prefix, long suffix) {
		ByteBuffer buffer = ByteBuffer.allocate(36);
		if (prefix < 0) {
			buffer.put((byte) 255).putLong(prefix);
		} else {
			Varint.writeUnsigned(buffer, prefix);
		}
		Varint.writeListUnsigned(buffer, new long[] { suffix, 0, 0 });
		return Arrays.copyOf(buffer.array(), buffer.position());
	}

	private static byte[] key(long... fields) {
		ByteBuffer buffer = ByteBuffer.allocate(36);
		Varint.writeListUnsigned(buffer, fields);
		return Arrays.copyOf(buffer.array(), buffer.position());
	}

	private static void check(int code) {
		assertEquals(0, code, () -> "LMDB: " + mdb_strerror(code));
	}

	private static void awaitLatch(CountDownLatch latch) {
		try {
			if (!latch.await(10, TimeUnit.SECONDS)) {
				throw new AssertionError("Native cancellation did not release the exact page walk");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError("Exact page walk was interrupted before native cancellation", e);
		}
	}

	private static final class Environment implements AutoCloseable {
		private final long handle;
		private final int records;
		private final LmdbPageCardinalityEstimator estimator;

		private Environment(Path directory, int flags) throws Exception {
			try (var stack = stackPush()) {
				var pointer = stack.mallocPointer(1);
				check(mdb_env_create(pointer));
				handle = pointer.get(0);
				check(mdb_env_set_mapsize(handle, 64L << 20));
				check(mdb_env_set_maxdbs(handle, 2));
				check(mdb_env_open(handle, directory.toString(), MDB_NOTLS, 0664));
				long txn = begin(0);
				try {
					var dbi = stack.mallocInt(1);
					check(mdb_dbi_open(txn, (ByteBuffer) null, 0, dbi));
					int main = dbi.get(0);
					check(mdb_dbi_open(txn, "records", MDB_CREATE | flags, dbi));
					records = dbi.get(0);
					check(mdb_txn_commit(txn));
					txn = NULL;
					estimator = new LmdbPageCardinalityEstimator(directory.resolve("data.mdb").toFile(), handle, main);
				} finally {
					if (txn != NULL) {
						mdb_txn_abort(txn);
					}
				}
			}
		}

		private long begin(int flags) {
			try (var stack = stackPush()) {
				var pointer = stack.mallocPointer(1);
				check(mdb_txn_begin(handle, NULL, flags, pointer));
				return pointer.get(0);
			}
		}

		private void write(int from, int to) {
			long txn = begin(0);
			try (var stack = stackPush()) {
				MDBVal key = MDBVal.malloc(stack);
				MDBVal value = MDBVal.malloc(stack).mv_data(stack.bytes((byte) 0));
				ByteBuffer bytes = stack.malloc(36);
				for (int row = from; row < to; row++) {
					bytes.clear();
					Varint.writeListUnsigned(bytes, new long[] { row / 500, row, 0, 0 });
					bytes.flip();
					key.mv_data(bytes);
					check(mdb_put(txn, records, key, value, 0));
				}
				check(mdb_txn_commit(txn));
				txn = NULL;
			} finally {
				if (txn != NULL) {
					mdb_txn_abort(txn);
				}
			}
		}

		private void writeUnsignedPrefixes(long[] prefixes) {
			long txn = begin(0);
			try (var stack = stackPush()) {
				MDBVal key = MDBVal.malloc(stack);
				MDBVal value = MDBVal.malloc(stack).mv_data(stack.bytes((byte) 0));
				for (long prefix : prefixes) {
					for (long suffix = 0; suffix < 2; suffix++) {
						byte[] raw = unsignedKey(prefix, suffix);
						ByteBuffer bytes = stack.malloc(raw.length).put(raw).flip();
						key.mv_data(bytes);
						check(mdb_put(txn, records, key, value, 0));
					}
				}
				check(mdb_txn_commit(txn));
				txn = NULL;
			} finally {
				if (txn != NULL) {
					mdb_txn_abort(txn);
				}
			}
		}

		@Override
		public void close() throws Exception {
			try {
				estimator.close();
			} finally {
				mdb_env_close(handle);
			}
		}
	}
